Tool response:
Tool: update_mobile_credential
Description: Update Mobile Credential
Parameters:
    {
      "type": "object",
      "properties": {
        "credential_number": {
          "type": "string",
          "description": "The credential number of the mobile credential to update",
          "title": "Credential Number"
        },
        "device_identifier": {
          "type": "string",
          "title": "Device Identifier"
        },
        "expiration_date": {
          "type": "string",
          "title": "Expiration Date"
        }
      },
      "required": [
        "credential_number"
      ]
    }
